<script setup lang="ts">
import {ref,computed} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from './session'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('PurchaseOrderCreate'),props=defineProps<{stores:string[],warehouses:any[],importOnly?:boolean}>(),emit=defineEmits<{created:[]}>()
const visible=ref(false),mode=ref('manual'),busy=ref(false),error=ref(''),rows=ref<any[]>([]),products=ref<any[]>([]),upload=ref<any>(null),previewHash=ref(''),requestId=ref('')
const routes=[['UK_air','英国空派'],['UK_truck','英国卡航'],['UK_sea','英国海运'],['DE_air','德国空派'],['DE_truck','德国卡航'],['DE_sea','德国海运']]
function id(){const s=Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`}
let fingerprint=''
function add(){rows.value.push({key:id(),product_id:null,warehouse_id:props.warehouses[0]?.id,store:'',quantity:1,quantities:Object.fromEntries(routes.map(([k])=>[k,0])),expected_date:'',unit_cost:null,supplier:'',extra_cost:0})}
async function search(q=''){try{products.value=(await api('/products?'+new URLSearchParams({q,page_size:'50'}))).rows}catch(e){error.value=(e as Error).message}}
function productChanged(row:any){const p=products.value.find(p=>p.id===row.product_id);if(p){row.code=p.code;row.name=p.name;row.unit_cost=Number(p.cost_cny||0);row.supplier=p.primary_supplier||''}}
async function open(value:string){mode.value=value;rows.value=[];upload.value=null;previewHash.value='';error.value='';requestId.value=id();fingerprint='';visible.value=true;if(value==='manual'){add();await search()}}
const invalid=computed(()=>!rows.value.length||rows.value.some(r=>!r.product_id||!r.warehouse_id||!r.expected_date||!Number.isInteger(r.quantity)||r.quantity<=0||Object.values(r.quantities).reduce((n:number,v:any)=>n+(Number(v)||0),0)>r.quantity))
async function pick(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;rows.value=[];error.value='';if(!file.name.endsWith('.xlsx')||file.size>5*1024*1024){error.value='请选择5MB以内xlsx文件';return}busy.value=true;try{const content=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]!);r.onerror=()=>reject(new Error('文件读取失败'));r.readAsDataURL(file)});upload.value={filename:file.name,content};const d=await api('/procurement/flow/import/preview',upload.value);rows.value=d.rows;previewHash.value=d.preview_hash;requestId.value=id()}catch(e){error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
async function save(){if(invalid.value||busy.value)return;busy.value=true;error.value='';try{let d;if(mode.value==='import')d=await api('/procurement/flow/import/commit',{...upload.value,preview_hash:previewHash.value,request_id:requestId.value});else{const values=rows.value.map(r=>({product_id:r.product_id,warehouse_id:r.warehouse_id,store:r.store||'',quantity:r.quantity,quantities:Object.fromEntries(routes.map(([k])=>[k,r.quantities[k!]||0])),expected_date:r.expected_date,unit_cost:r.unit_cost,supplier:r.supplier||'',extra_cost:r.extra_cost||0}));const next=JSON.stringify(values);if(fingerprint&&fingerprint!==next)requestId.value=id();fingerprint=next;d=await api('/procurement/flow/orders',{request_id:requestId.value,rows:values})}visible.value=false;emit('created');ElMessage.success(`已新增 ${new Set(d.orders.map((o:any)=>o.number)).size} 张采购单`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><el-button v-if="!importOnly" @click="open('manual')">新增采购单</el-button><el-button @click="open('import')">Excel 导入</el-button>
<el-dialog v-model="visible" :title="mode==='import'?'Excel 导入采购单':'新增采购单'" width="min(1800px,96vw)" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy">
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div class="create-actions"><template v-if="mode==='import'"><a href="/api/procurement/flow/import/template" download>下载 Excel 模板</a><input type="file" accept=".xlsx" :disabled="busy" @change="pick"/></template><el-button v-else type="primary" :disabled="busy" @click="add">新增商品</el-button><TableReset table-key="PurchaseOrderCreate/lines"/></div>
<template v-if="true"><el-table border :data="rows" max-height="480" data-width-key="PurchaseOrderCreate/lines" @header-dragend="(w:number,_o:number,c:any)=>widths.resize('lines',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>widths.resetColumn('lines',c,e)">
<el-table-column column-key="product" label="标品编码（必填）" :width="widths.width('lines','product',280)"><template #default="{row}"><span v-if="mode==='import'">{{row.code}} · {{row.name}}</span><el-select v-else v-model="row.product_id" filterable remote :remote-method="search" placeholder="搜索标品编码" @change="productChanged(row)"><el-option v-for="p in products" :key="p.id" :value="p.id" :label="p.code+' · '+p.name"/></el-select></template></el-table-column>
<el-table-column column-key="warehouse" label="仓库（必填）" :width="widths.width('lines','warehouse',150)"><template #default="{row}"><span v-if="mode==='import'">{{row.warehouse_name}}</span><el-select v-else v-model="row.warehouse_id"><el-option v-for="w in props.warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></template></el-table-column>
<el-table-column column-key="store" label="店铺（选填）" :width="widths.width('lines','store',145)"><template #default="{row}"><span v-if="mode==='import'">{{row.store||'未指定'}}</span><el-select v-else v-model="row.store" clearable placeholder="可稍后指定"><el-option v-for="s in props.stores" :key="s" :value="s" :label="s"/></el-select></template></el-table-column>
<el-table-column column-key="quantity" label="采购数量" :width="widths.width('lines','quantity',120)" align="center"><template #default="{row}"><span v-if="mode==='import'">{{row.quantity}}</span><el-input-number v-else v-model="row.quantity" :min="1" :max="100000000" :precision="0" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column v-for="[key,label] in routes" :key="key" :column-key="key" :label="label" :width="widths.width('lines',key!,115)" align="center"><template #default="{row}"><span v-if="mode==='import'">{{row.quantities[key!]||0}}</span><el-input-number v-else v-model="row.quantities[key!]" :min="0" :max="row.quantity" :precision="0" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column column-key="date" label="预计到货时间" :width="widths.width('lines','date',170)"><template #default="{row}"><span v-if="mode==='import'">{{row.expected_date}}</span><el-date-picker v-else v-model="row.expected_date" type="date" value-format="YYYY-MM-DD" style="width:100%"/></template></el-table-column>
<el-table-column column-key="supplier" label="供应商" :width="widths.width('lines','supplier',160)"><template #default="{row}"><span v-if="mode==='import'">{{row.supplier}}</span><el-input v-else v-model="row.supplier" maxlength="500" placeholder="默认商品供应商"/></template></el-table-column>
<el-table-column column-key="cost" label="采购单价 (¥)" :width="widths.width('lines','cost',145)" align="center"><template #default="{row}"><span v-if="mode==='import'">{{row.unit_cost}}</span><el-input-number v-else v-model="row.unit_cost" :min="0" :precision="4" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column column-key="extra" label="其他费用 (¥)" :width="widths.width('lines','extra',145)" align="center"><template #default="{row}"><span v-if="mode==='import'">{{row.extra_cost}}</span><el-input-number v-else v-model="row.extra_cost" :min="0" :precision="4" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column v-if="mode==='manual'" column-key="actions" label="操作" fixed="right" width="80"><template #default="{row}"><el-button link type="danger" @click="rows.splice(rows.indexOf(row),1)">删除</el-button></template></el-table-column>
</el-table></template><p>店铺、六个渠道可暂不填写，生成发货计划时补全。渠道合计不得超过采购数量。同供应商、同预计到货日期合并为一张采购单。</p><p>供应商和单价默认读取商品中心，未维护时为“未填写”和 0，请按实际采购信息核对。</p>
<template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :disabled="invalid" :loading="busy" @click="save">{{mode==='import'?'确认导入采购单':'保存采购单'}}</el-button></template></el-dialog></template>
<style scoped>:deep(.el-table .cell){padding:0 8px;text-overflow:clip}.create-actions{display:flex;justify-content:flex-end;gap:20px;margin:12px 0}.create-actions a{color:#237863}p{color:#788e82;font-size:13px;line-height:1.7}</style>
